 [Fact] public void ReplayJournalForwarderIsStillByRef(){string r=Read("HybridCPU_ISE","CloseToHSL","Core","State","CPU_Core.RuntimeState.cs");Assert.Contains("private ref System.Collections.Generic.Dictionary<ulong",r);Assert.Contains("ref Runtime.Extensions.MatrixTileReplayJournals;",r);Assert.DoesNotContain("private readonly ref",r);}
 [Fact] public void OwnershipPredicateBodyIsUnchanged(){string m=Read("HybridCPU_ISE","CloseToHSL","Core","Pipeline","Retire","Evidence","CPU_Core.MatrixTileRetireState.cs");Order(m,"internal bool OwnsMatrixTileReplayJournal(","_matrixTileReplayJournals.TryGetValue(","ReferenceEquals(registered, journal)");Assert.Contains("if (!OwnsMatrixTileReplayJournal(journal)",m);}
 [Fact] public void EvidenceAuthorizesAtomicConversionNext(){string e=Read("Documentation", "ArchitectureAuthorityRefactor","Evidence","RF11","rf11.48-struct-only-instance-modifier-hardening.md");string l=Read("Documentation", "ArchitectureAuthorityRefactor","10_RF11","00_CURRENT_STATUS_AND_LEDGER.md");Assert.Contains("no storage",e,StringComparison.OrdinalIgnoreCase);Assert.Contains("--minimal-logs",e);Assert.Contains("RF-11.49",l);}
 static void Order(string s,params string[] m){int p=-1;foreach(string x in m){int n=s.IndexOf(x,p+1,StringComparison.Ordinal);Assert.True(n>p,x);p=n;}}static string Read(params string[] p)=>File.ReadAllText(p.Aggregate(Root(),Path.Combine));static string Root(){string? c=AppContext.BaseDirectory;while(c!=null){if(File.Exists(Path.Combine(c,"HybridCPU v2.slnx")))return c;c=Directory.GetParent(c)?.FullName;}throw new DirectoryNotFoundException();}
